+    return candidates(command).find(isFile) ?? null;
+  }
+  const dirs = (env.pathEnv ?? process.env.PATH ?? "").split(win ? ";" : ":").filter(Boolean);
+  for (const dir of dirs) {
+    const hit = candidates(p.join(dir.replace(/^"|"$/g, ""), command)).find(isFile);
+    if (hit) return hit;
+  }
+  return null;
