+  const platform = env.platform ?? process.platform;
+  const win = platform === "win32";
+  const p = win ? pathWin32 : pathPosix;
+  const exts = win ? (env.pathExt ?? process.env.PATHEXT ?? ".COM;.EXE;.BAT;.CMD").split(";").filter(Boolean) : [];
